    #d8 0x10, 0x13, 0x16, 0x19, 0x1C, 0x1F, 0x23, 0x26, 0x29, 0x2C, 0x30, 0x33, 0x36, 0x3A, 0x3D, 0x41
    #d8 0x44, 0x48, 0x4B, 0x4F, 0x52, 0x56, 0x5A, 0x5D, 0x61, 0x65, 0x69, 0x6C, 0x70, 0x74, 0x78, 0x7C
    #d8 0x00, 0x04, 0x08, 0x0C, 0x10, 0x14, 0x19, 0x1D, 0x21, 0x25, 0x2A, 0x2E, 0x32, 0x37, 0x3B, 0x40
    #d8 0x44, 0x49, 0x4D, 0x52, 0x56, 0x5B, 0x60, 0x64, 0x69, 0x6E, 0x73, 0x77, 0x7C, 0x01, 0x06, 0x0B
    #d8 0x10, 0x15, 0x1A, 0x1F, 0x24, 0x29, 0x2F, 0x34, 0x39, 0x3E, 0x44, 0x49, 0x4E, 0x54, 0x59, 0x5F
    #d8 0x64, 0x6A, 0x6F, 0x75, 0x7A, 0x00, 0x06, 0x0B, 0x11, 0x17, 0x1D, 0x22, 0x28, 0x2E, 0x34, 0x3A
    #d8 0x40, 0x46, 0x4C, 0x52, 0x58, 0x5E, 0x65, 0x6B, 0x71, 0x77, 0x7E, 0x04, 0x0A, 0x11, 0x17, 0x1E
    #d8 0x24, 0x2B, 0x31, 0x38, 0x3E, 0x45, 0x4C, 0x52, 0x59, 0x60, 0x67, 0x6D, 0x74, 0x7B, 0x02, 0x09
    #d8 0x10, 0x17, 0x1E, 0x25, 0x2C, 0x33, 0x3B, 0x42, 0x49, 0x50, 0x58, 0x5F, 0x66, 0x6E, 0x75, 0x7D
    #d8 0x04, 0x0C, 0x13, 0x1B, 0x22, 0x2A, 0x32, 0x39, 0x41, 0x49, 0x51, 0x58, 0x60, 0x68, 0x70, 0x78
#addr 0x0200
sq_hi:
    #d8 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
    #d8 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
    #d8 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
    #d8 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
    #d8 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
    #d8 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x01, 0x01, 0x01, 0x01, 0x01
    #d8 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01
    #d8 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01
    #d8 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02
    #d8 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x03, 0x03, 0x03
    #d8 0x03, 0x03, 0x03, 0x03, 0x03, 0x03, 0x03, 0x03, 0x03, 0x03, 0x03, 0x03, 0x03, 0x03, 0x03, 0x03
    #d8 0x03, 0x03, 0x03, 0x03, 0x03, 0x04, 0x04, 0x04, 0x04, 0x04, 0x04, 0x04, 0x04, 0x04, 0x04, 0x04
    #d8 0x04, 0x04, 0x04, 0x04, 0x04, 0x04, 0x04, 0x04, 0x04, 0x04, 0x04, 0x05, 0x05, 0x05, 0x05, 0x05
    #d8 0x05, 0x05, 0x05, 0x05, 0x05, 0x05, 0x05, 0x05, 0x05, 0x05, 0x05, 0x05, 0x05, 0x05, 0x06, 0x06
    #d8 0x06, 0x06, 0x06, 0x06, 0x06, 0x06, 0x06, 0x06, 0x06, 0x06, 0x06, 0x06, 0x06, 0x06, 0x06, 0x06
    #d8 0x07, 0x07, 0x07, 0x07, 0x07, 0x07, 0x07, 0x07, 0x07, 0x07, 0x07, 0x07, 0x07, 0x07, 0x07, 0x07
#addr 0x0300
colors:
    #d8 0x00, 0x04, 0x08, 0x0F, 0x07, 0x0D, 0x05, 0x09, 0x01, 0x0B, 0x03, 0x0A, 0x02, 0x0E, 0x06, 0x0C, 0x04, 0x04, 0x08, 0x0F, 0x07, 0x0D, 0x05, 0x09, 0x01, 0x0B, 0x03, 0x0A, 0x02, 0x0E, 0x06, 0x0C, 0x04

#addr 0x0400
main:
    ; mode byte (byte column 0) = 2 (4 bpp) for all 480 rows: 6020-61FF
    ld   0x60, y
    ld   0x20, x
mode0:
    ld   0x02, [y,x]
    ld   x, ac
    inc
    ld   ac, x
    bne  mode0
    ld   0x61, y
mode1:
    ld   0x02, [y,x]
    ld   x, ac
    inc
    ld   ac, x
    bne  mode1

    ; px = 0: cx = -128 = (hi -1, lo 0)
    ld   0x62, ac
    ld   ac, [0x2F]
    ld   0xFF, ac
    ld   ac, [0x2A]
    ld   0x00, ac
    ld   ac, [0x29]
    ld   0x4F, ac
    ld   ac, [0x30]
col:
    ld   [0x2F], ac
    ld   ac, [0x2E]
    ld   0x20, ac
    ld   ac, [0x2D]
    ; py = 0: cy = -60 = (hi -1, lo 68)
    ld   0xFF, ac
    ld   ac, [0x25]
    ld   0x44, ac
    ld   ac, [0x24]
    ld   0x78, ac
    ld   ac, [0x31]
row:
    ; left point (low nibble)
    ld   [0x29], ac
    ld   ac, [0x22]
    ld   [0x2A], ac
    ld   ac, [0x23]
    ld   ret_l, ac
    ld   ac, [0x27]
    ld   ret_l >> 8, ac
    ld   ac, [0x28]
    ld   kernel >> 8, y
    jmp  kernel
ret_l:
    ld   ac, [0x2B]
    ; right point (high nibble): cx + 1, lo is even so no carry
    ld   [0x29], ac
    inc
    ld   ac, [0x22]
    ld   ret_r, ac
    ld   ac, [0x27]
    ld   ret_r >> 8, ac
    ld   ac, [0x28]
    ld   kernel >> 8, y
    jmp  kernel
ret_r:
    shl
    shl
    shl
    shl
    or   [0x2B], ac
    ld   ac, [0x2C]
    ; write the byte to 4 screen rows
    ld   [0x2D], x
    ld   [0x2E], y
    ld   ac, [y,x]
    ld   x, ac
    inc
    ld   ac, x
    ld   [0x2C], ac
    ld   ac, [y,x]
    ld   x, ac
    inc
    ld   ac, x
    ld   [0x2C], ac
    ld   ac, [y,x]
    ld   x, ac
    inc
    ld   ac, x
    ld   [0x2C], ac
    ld   ac, [y,x]
    ld   x, ac
    inc
    ld   ac, x
    ld   ac, [0x2D]
    bne  nowrap
    ld   [0x2E], ac
    inc
    ld   ac, [0x2E]
nowrap:
    ; cy += 1/64
    ld   [0x24], ac
    inc
    bge  cyok
    ld   [0x25], ac
    inc
    ld   ac, [0x25]
    clr  ac
cyok:
    ld   ac, [0x24]
    ld   [0x31], ac
    dec
    ld   ac, [0x31]
    bne  row
    ; next byte column: cx0 += 2/64, video page += 2
    ld   [0x29], ac
    add  2, ac
    bge  cxok
    and  0x7F, ac
    ld   ac, [0x29]
    ld   [0x2A], ac
    inc
    ld   ac, [0x2A]
    bra  cxdone
cxok:
    ld   ac, [0x29]
cxdone:
    ld   [0x2F], ac
    add  2, ac
    ld   ac, [0x2F]
    ld   [0x30], ac
    dec
    ld   ac, [0x30]
    bne  col
done:
    bra  done

; iteration kernel: in cx, cy; out AC = color; returns to [reth, ret]
#addr 0x0500
kernel:
    clr  ac
    ld   ac, [0x10]
    ld   ac, [0x12]
    ld   ac, [0x11]
    ld   ac, [0x13]
    ld   0x20, ac
    ld   ac, [0x26]
iter:
    ; x*x, y*y from the square table
    ld   [0x10], x
    ld   0x01, y
    ld   [y,x], ac
    ld   ac, [0x14]
    ld   0x02, y
    ld   [y,x], ac
    ld   ac, [0x15]
    ld   [0x12], x
    ld   [y,x], ac
    ld   ac, [0x17]
    ld   0x01, y
    ld   [y,x], ac
    ld   ac, [0x16]
    ; t = x*x + y*y, escape if t >= 4.0 (hi >= 2)
    ld   [0x14], ac
    add  [0x16], ac
    bge  nc_1
    and  0x7F, ac
    ld   ac, [0x18]
    ld   [0x15], ac
    add  [0x17], ac
    inc
    bra  ad_2
nc_1:
    ld   ac, [0x18]
    ld   [0x15], ac
    add  [0x17], ac
ad_2:
    ld   ac, [0x19]
    sub  2, ac
    bge  escape
    ; x' = x*x - y*y + cx
    ld   [0x14], ac
    sub  [0x16], ac
    bge  nb_3
    and  0x7F, ac
    ld   ac, [0x1A]
    ld   [0x15], ac
    sub  [0x17], ac
    dec
    bra  sd_4
nb_3:
    ld   ac, [0x1A]
    ld   [0x15], ac
    sub  [0x17], ac
sd_4:
    ld   ac, [0x1B]
    ld   [0x1A], ac
    add  [0x22], ac
    bge  nc_5
    and  0x7F, ac
    ld   ac, [0x1C]
    ld   [0x1B], ac
    add  [0x23], ac
    inc
    bra  ad_6
nc_5:
    ld   ac, [0x1C]
    ld   [0x1B], ac
    add  [0x23], ac
ad_6:
    ld   ac, [0x1D]
    ; s = |x + y|
    ld   [0x11], ac
    xor  [0x13], ac
    bne  sdiff
    ld   [0x10], ac
    add  [0x12], ac
    bra  sdone
sdiff:
    ld   [0x10], ac
    sub  [0x12], ac
    bge  sdone
    ld   [0x12], ac
    sub  [0x10], ac
sdone:
    ld   ac, x
    ld   0x01, y
    ld   [y,x], ac
    ld   ac, [0x1E]
    ld   0x02, y
    ld   [y,x], ac
    ld   ac, [0x1F]
    ld   kernel2 >> 8, y
    jmp  kernel2
    ; done: color from the iterations left (kept in the kernel page,
    ; bge escape above is an 8-bit branch)
escape:
    ld   [0x26], x
    ld   0x03, y
    ld   [y,x], ac
    ld   [0x28], y
    jmp  [0x27]

#addr 0x0600
kernel2:
    ; y' = s*s - t + cy  (= 2xy + cy)
    ld   [0x1E], ac
    sub  [0x18], ac
    bge  nb_7
    and  0x7F, ac
    ld   ac, [0x20]
    ld   [0x1F], ac
    sub  [0x19], ac
    dec
    bra  sd_8
nb_7:
    ld   ac, [0x20]
    ld   [0x1F], ac
    sub  [0x19], ac
sd_8:
    ld   ac, [0x21]
    ld   [0x20], ac
    add  [0x24], ac
    bge  nc_9
    and  0x7F, ac
    ld   ac, [0x20]
    ld   [0x21], ac
    add  [0x25], ac
    inc
    bra  ad_10
nc_9:
    ld   ac, [0x20]
    ld   [0x21], ac
    add  [0x25], ac
ad_10:
    ld   ac, [0x21]
    ; back to magnitude + sign, escape if |x'| or |y'| >= 2
    ld   [0x1D], ac
    beq  pos_11
    inc                     ; hi must be -1
    bne  escape2
    ld   [0x1C], ac
    beq  escape2              ; -128 = -2.0
    ld   0x80, ac
    sub  [0x1C], ac
    ld   ac, [0x10]
    ld   1, ac
    ld   ac, [0x11]
    bra  sm_12
pos_11:
    ld   [0x1C], ac
    ld   ac, [0x10]
    clr  ac
    ld   ac, [0x11]
sm_12:
    ld   [0x21], ac
    beq  pos_13
    inc                     ; hi must be -1
    bne  escape2
    ld   [0x20], ac
    beq  escape2              ; -128 = -2.0
    ld   0x80, ac
    sub  [0x20], ac
    ld   ac, [0x12]
    ld   1, ac
    ld   ac, [0x13]
    bra  sm_14
pos_13:
    ld   [0x20], ac
    ld   ac, [0x12]
    clr  ac
    ld   ac, [0x13]
sm_14:
    ld   [0x26], ac
    dec
    ld   ac, [0x26]
    beq  escape2             ; never escaped: it = 0 -> black
    ld   iter >> 8, y
    jmp  iter
escape2:
    ld   escape >> 8, y
    jmp  escape
